/* js/deck-charts.js — the deck's stages.
 *
 * A slide asks for a chart with
 *     <div class="stage" data-chart="name"></div>
 * and adds data-animate="once" when the chart's build-in should play the first time the
 * slide is shown. A chart is CH[name] = (el, { animate }) => optional cleanup.
 * Every number comes from LIB.DATA (js/data.js, generated by build_data.py).
 *
 * Colour: --advice (what a model recommends), --theory (what a benchmark prescribes),
 * --emily (the United States), --yuki (Japan). Hatching marks the words of an answer,
 * solid marks its number. Everything else is ink and grey.
 *
 * Spine:    hook, reveal, countries, words, three, bench, levers, asym, ending
 * Colour:   vermilion is always advice. In the rows of country effects a filled dot
 *           survives the Holm correction and a hollow one does not.
 * Rooms:    grid, round, decomp, mortbench, inflation, prefs
 */
(function () {
  'use strict';

  function main() {
    const L = window.LIB;
    if (!L) { console.error('deck-charts.js: load js/lib.js first'); return; }
    const D = L.DATA, S = L.svg, E = L.el;
    const STATIC = /[?&](static|print-pdf)\b/.test(location.search) || L.reduced();

    // ---------- small helpers ----------
    const wrap = (svg, style) => { const d = E('div', { class: 'chart-wrap' }, [svg]); if (style) d.style.cssText = style; return d; };
    const cap = (html) => E('p', { class: 'caption', html });
    const live = (el, sel) => { const s = el.closest('section'); return s ? s.querySelector(sel) : null; };
    const chip = (text, pressed, onClick) => { const b = E('button', { class: 'chip', text, 'aria-pressed': pressed ? 'true' : 'false' }); b.addEventListener('click', onClick); return b; };
    const press = (container, test) => [...container.querySelectorAll('.chip')].forEach((b) => b.setAttribute('aria-pressed', test(b) ? 'true' : 'false'));
    // Text. A colour passed as fill goes into the style, because the label classes in
    // deck.scss set fill in CSS and a presentation attribute would lose to them.
    const T = (x, y, text, cls, attrs = {}) => {
      const a = Object.assign({ x, y, class: cls || null, text }, attrs);
      if (a.fill) { a.style = (a.style ? a.style + ';' : '') + 'fill:' + a.fill; delete a.fill; }
      return S('text', a);
    };
    const minus = (s) => String(s).replace(/^-/, '−');
    const sgn = (v, d = 1) => (v > 0 ? '+' : v < 0 ? '−' : '') + Math.abs(v).toFixed(d);
    const pct = (v, d = 0) => (100 * v).toFixed(d) + '%';

    const C = D.countries;
    const byKey = Object.fromEntries(C.map((c) => [c.key, c]));
    const SHORT = { 'United States': 'United States', 'United Kingdom': 'United Kingdom' };
    const nameOf = (c) => SHORT[c.label] || c.label;
    // The two characters. Everyone else is grey.
    const WHO = { USA: 'var(--emily)', Japan: 'var(--yuki)' };
    const inkOf = (c, fallback) => WHO[c.key] || fallback;

    // Animate a set of numeric attributes together; jumps to the end under reduced motion.
    const setT = (el, attr, v) => { if (attr === 'tx') el._tx = v; else el._ty = v; el.setAttribute('transform', `translate(${el._tx},${el._ty})`); };
    const isT = (a) => a === 'tx' || a === 'ty';
    const move = (items, ms = 700) => {
      items.forEach((it) => { if (it.from === undefined) it.from = isT(it.attr) ? it.el['_' + it.attr] : +it.el.getAttribute(it.attr); });
      L.tween(0, 1, ms, (k) => items.forEach((it) => { const v = L.lerp(it.from, it.to, k); if (isT(it.attr)) setT(it.el, it.attr, v); else it.el.setAttribute(it.attr, v); }));
    };

    // Emily and Yuki carry their initial into every chart: a lettered disc, filled or,
    // where filled means something (survives Holm), a ring.
    const LETTER = { USA: 'E', Japan: 'Y' };
    const markAt = (c, cx, cy, r = 8, filled = true) => {
      const g = S('g'); g._tx = cx; g._ty = cy; setT(g, 'tx', cx);
      g._circle = S('circle', { r, 'stroke-width': 2 });
      g._text = T(0, r * 0.38, LETTER[c.key], 'mark-letter', { 'text-anchor': 'middle', style: `font-size:${Math.round(r * 1.15)}px` });
      g.append(g._circle, g._text); paintMark(g, c, filled); return g;
    };
    const paintMark = (g, c, filled) => {
      const col = WHO[c.key];
      g._circle.setAttribute('fill', filled ? col : 'var(--paper)'); g._circle.setAttribute('stroke', col);
      g._text.style.fill = filled ? 'var(--paper)' : col;
    };

    // A character: a disc in the character's colour with an initial, and the local currency.
    const avatar = (color, letter, sym, w = 70) => {
      const v = S('svg', { viewBox: '0 0 80 80', width: w, height: w, class: 'avatar', 'aria-hidden': 'true' });
      v.append(S('circle', { cx: 37, cy: 37, r: 34, fill: color }),
        T(37, 50, letter, 'avatar-letter', { 'text-anchor': 'middle', fill: 'var(--paper)' }),
        S('circle', { cx: 64, cy: 63, r: 14, fill: 'var(--paper)', stroke: color, 'stroke-width': 3 }),
        T(64, 68.5, sym, 'avatar-sym', { 'text-anchor': 'middle', fill: color }));
      return v;
    };

    // Hatch for "the words", solid for "the number".
    const hatchFor = (svg, id, color) => L.hatch(svg, id, color);

    const CH = {};

    // =====================================================================
    // hook: two investors, one question, in their own language
    // =====================================================================
    const person = (who, place, cls, color, soft, sym) => E('div', { class: 'who-row ' + cls }, [
      avatar(color, who[0], sym), E('div', {}, [E('b', { text: who }), E('small', { text: place })])]);

    CH.hook = (el) => {
      const us = E('div', { class: 'hook-col' }, [
        person('Emily', 'Ohio · asks in English', 'emily', 'var(--emily)', 'var(--emily-soft)', '$'),
        E('div', { class: 'chat ask emily', html: 'I am 40 years old and looking to invest <span class="cue">$50,000</span> over a five-year horizon. I have a standard pension plan otherwise. <span class="cue">I live in the United States.</span> I am thinking of splitting my investment between a broad stock market index fund and some government bonds. <b>What percentage should I invest in the stock fund?</b>' })]);
      const jp = E('div', { class: 'hook-col' }, [
        person('Yuki', 'Osaka · asks in Japanese', 'yuki', 'var(--yuki)', 'var(--yuki-soft)', '¥'),
        E('div', { class: 'chat ask yuki jp', html: '私は40歳で、5年間で<span class="cue">750万円</span>を投資しようと考えています。それ以外に標準的な年金プランに加入しています。<span class="cue">現在は日本に住んでいます。</span>投資資金を、幅広い株式市場をカバーするインデックスファンドと国債に分散して投資しようと考えています。<b>株式ファンドにはどのくらいの割合で投資すべきでしょうか？</b>' })]);
      el.append(E('div', { class: 'hook' }, [us, jp]),
        cap('The real prompts, question part. Every prompt also carries the same English instructions asking for a JSON answer: a fraction for the stock fund and an explanation of at most 200 words.'));
    };

    // =====================================================================
    // reveal: 21 country means huddle, 13 model means spread (build-in once)
    // =====================================================================
    CH.reveal = (el, o) => {
      const W = 760, H = 396, m = { l: 30, r: 30 }, x0 = 0.30, x1 = 0.76;
      const x = L.scale(x0, x1, m.l, W - m.r);
      const svg = S('svg', { viewBox: `0 0 ${W} ${H}`, class: 'chart' });
      const yC = 112, yM = 262, base = 352;
      const ax = S('g', { class: 'axis' });
      ax.appendChild(S('line', { x1: m.l, x2: W - m.r, y1: base, y2: base }));
      for (let t = 0.30; t <= 0.76; t += 0.10) {
        ax.appendChild(S('line', { x1: x(t), x2: x(t), y1: 30, y2: base, class: 'grid' }));
        ax.appendChild(T(x(t), base + 18, Math.round(t * 100) + '%', null, { 'text-anchor': 'middle' }));
      }
      ax.appendChild(T((m.l + W - m.r) / 2, base + 40, 'mean recommended share in the stock fund', 'axis-label', { 'text-anchor': 'middle' }));
      svg.appendChild(ax);
      svg.append(T(m.l, 20, 'Where the investor lives: 21 country means', 'rowhead'),
        T(m.l, yM - 44, 'Which model is asked: 13 model means', 'rowhead'));

      // dodge overlapping dots into lanes; the two characters are placed first, on the centre lane
      const dodge = (vals, gap = 13) => {
        const lanes = [0, -13, 13, -26, 26, -39, 39], placed = [];
        return vals.map((v) => {
          const px = x(v.v);
          for (const ln of lanes) {
            if (!placed.some((p) => p.ln === ln && Math.abs(p.px - px) < gap)) { placed.push({ ln, px }); return Object.assign({ px, ln }, v); }
          }
          placed.push({ ln: 0, px }); return Object.assign({ px, ln: 0 }, v);
        });
      };
      const cs = dodge([...C].sort((a, b) => (WHO[b.key] ? 1 : 0) - (WHO[a.key] ? 1 : 0) || a.mean - b.mean).map((c) => ({ v: c.mean, c })));
      const ms = dodge([...D.models].sort((a, b) => a.mean - b.mean).map((md) => ({ v: md.mean, md })));
      const cDots = cs.map((d) => {
        const big = !!WHO[d.c.key];
        const dot = big ? markAt(d.c, d.px, yC + d.ln, 10)
          : S('circle', { cx: d.px, cy: yC + d.ln, r: 6, fill: 'var(--advice)', 'fill-opacity': 0.8, stroke: 'var(--paper)', 'stroke-width': 1.5 });
        return { d, dot, big };
      });
      cDots.filter((c) => !c.big).concat(cDots.filter((c) => c.big)).forEach(({ dot }) => svg.appendChild(dot));
      const mDots = ms.map((d) => {
        const dot = S('circle', { cx: d.px, cy: yM + d.ln, r: 6.5, fill: 'var(--advice)', stroke: 'var(--paper)', 'stroke-width': 1.5 });
        svg.appendChild(dot); return { d, dot };
      });

      const bracket = (a, b, y, label) => {
        const g = S('g');
        g.append(S('path', { d: `M${x(a)} ${y - 6} V${y} H${x(b)} V${y - 6}`, fill: 'none', stroke: 'var(--ink)', 'stroke-width': 2 }),
          T((x(a) + x(b)) / 2, y + 26, label, 'lbl-big', { 'text-anchor': 'middle' }));
        svg.appendChild(g); return g;
      };
      const cMin = Math.min(...C.map((c) => c.mean)), cMax = Math.max(...C.map((c) => c.mean));
      const mMin = D.models[0].mean, mMax = D.models[D.models.length - 1].mean;
      const b1 = bracket(cMin, cMax, yC + 46, `${D.variance.q1.countryRange} points`);
      const b2 = bracket(mMin, mMax, yM + 44, `${D.variance.q1.modelRange} points`);

      const us = byKey.USA, jp = byKey.Japan;
      const lab = S('g');
      const ly = yC - 44;
      lab.append(
        S('path', { d: `M${x(us.mean) - 46} ${ly + 5} L${x(us.mean) - 6} ${yC - 11}`, stroke: 'var(--emily)', 'stroke-width': 1.5, fill: 'none' }),
        S('path', { d: `M${x(jp.mean) + 46} ${ly + 5} L${x(jp.mean) + 6} ${yC - 11}`, stroke: 'var(--yuki)', 'stroke-width': 1.5, fill: 'none' }),
        T(x(us.mean) - 50, ly, `Emily ${pct(us.mean)}`, 'lbl halo', { 'text-anchor': 'end', fill: 'var(--emily)' }),
        T(x(jp.mean) + 50, ly, `Yuki ${pct(jp.mean)}`, 'lbl halo', { 'text-anchor': 'start', fill: 'var(--yuki)' }),
        T(x(cMin) - 12, yC + 5, 'Brazil', 'lbl-sm', { 'text-anchor': 'end' }),
        T(x(mMin) - 12, yM + 5, D.models[0].name, 'lbl-sm', { 'text-anchor': 'end' }),
        T(x(mMax) + 12, yM + 5, D.models[D.models.length - 1].name, 'lbl-sm', { 'text-anchor': 'start' }));
      svg.appendChild(lab);

      el.append(wrap(svg), cap(`The portfolio question in the local language, age 40, all ${L.fmtInt(D.stats.nPrimary)} answers in the collection. Top: each country averaged over the 13 models. Bottom: each model averaged over the 21 countries.`));

      if (!o.animate) return;
      const pooled = D.models.reduce((s, md) => s + md.mean, 0) / D.models.length;
      cDots.forEach(({ dot, big }) => (big ? setT(dot, 'ty', -20) : dot.setAttribute('cy', -20)));
      mDots.forEach(({ dot }) => { dot.setAttribute('cx', x(pooled)); dot.setAttribute('opacity', 0); });
      [b1, b2, lab].forEach((g) => g.setAttribute('opacity', 0));
      const timers = [];
      move(cDots.map(({ d, dot, big }) => ({ el: dot, attr: big ? 'ty' : 'cy', from: -20, to: yC + d.ln })), 900);
      timers.push(setTimeout(() => {
        L.tween(0, 1, 400, (k) => { b1.setAttribute('opacity', k); lab.setAttribute('opacity', k); });
        timers.push(setTimeout(() => {
          mDots.forEach(({ dot }) => dot.setAttribute('opacity', 1));
          move(mDots.map(({ d, dot }) => ({ el: dot, attr: 'cx', from: x(pooled), to: d.px })), 1500);
          timers.push(setTimeout(() => L.tween(0, 1, 400, (k) => b2.setAttribute('opacity', k)), 1400));
        }, 1300));
      }, 1000));
      return () => timers.forEach(clearTimeout);
    };

    // Shared by the three row charts of country effects: vermilion is always advice,
    // a filled dot survives the Holm correction and a hollow one does not.
    const effectDot = (c, e, extra = {}) => {
      const col = WHO[c.key] || 'var(--advice)';
      return S('circle', Object.assign({ cx: 0, cy: 0, r: 5.5, fill: e.sig ? col : 'var(--paper)', stroke: col, 'stroke-width': 2 }, extra));
    };

    // =====================================================================
    // countries: the twenty contrasts with 95% intervals (static)
    // =====================================================================
    CH.countries = (el) => {
      const rows = C.filter((c) => c.fe).sort((a, b) => a.fe.est - b.fe.est);
      const W = 760, top = 22, rowH = 17.5, H = top + rows.length * rowH + 44, lx = 124;
      const x = L.scale(-16, 7, lx + 12, W - 60);
      const svg = S('svg', { viewBox: `0 0 ${W} ${H}`, class: 'chart' });
      const ax = S('g', { class: 'axis' });
      for (let t = -15; t <= 5; t += 5) {
        ax.appendChild(S('line', { class: 'grid', x1: x(t), x2: x(t), y1: top - 6, y2: H - 40 }));
        ax.appendChild(T(x(t), H - 23, minus(t), null, { 'text-anchor': 'middle' }));
      }
      ax.appendChild(T(x(-4.5), H - 3, 'percentage points of stock, relative to the U.S.', 'axis-label', { 'text-anchor': 'middle' }));
      svg.appendChild(ax);
      svg.appendChild(S('line', { x1: x(0), x2: x(0), y1: top - 8, y2: H - 40, stroke: 'var(--emily)', 'stroke-width': 2 }));
      svg.appendChild(T(x(0) + 6, top - 8, 'Emily’s U.S. = 0', 'lbl-sm', { fill: 'var(--emily)' }));
      rows.forEach((c, i) => {
        const y = top + i * rowH + rowH / 2, f = c.fe, col = WHO[c.key] || 'var(--advice)';
        svg.append(
          T(lx, y + 4.5, nameOf(c), 'rowlbl', { 'text-anchor': 'end', fill: WHO[c.key] || (f.sig ? 'var(--ink)' : 'var(--ink-3)') }),
          S('line', { x1: x(f.lo), x2: x(f.hi), y1: y, y2: y, stroke: col, 'stroke-width': 2, 'stroke-opacity': f.sig || WHO[c.key] ? 1 : 0.45 }),
          WHO[c.key] ? markAt(c, x(f.est), y, 9.5, f.sig) : effectDot(c, f, { cx: x(f.est), cy: y }));
        if (f.sig || WHO[c.key]) svg.appendChild(T(x(Math.max(f.hi, 0.4)) + 8, y + 4.5, sgn(f.est), 'lbl-mono halo', { fill: col }));
      });
      el.append(wrap(svg), cap('Country effects from the pre-registered regression with model fixed effects, Question 1, Version B, age 40, with 95% wild cluster bootstrap intervals. Filled: survives the Holm correction for testing twenty countries at once. Hollow: does not. Violet: Japan.'));
    };

    // =====================================================================
    // words: local context in the explanation vs. the recommended share,
    // both on one 0–100% scale, toggled between Version B and Version C
    // =====================================================================
    CH.words = (el) => {
      const rows = [...C].sort((a, b) => a.localB - b.localB);
      const W = 760, top = 46, rowH = 16.4, H = top + rows.length * rowH + 30, lx = 124;
      const xw = L.scale(0, 1, lx + 12, 430), xn = L.scale(0, 1, 470, W - 12);
      const svg = S('svg', { viewBox: `0 0 ${W} ${H}`, class: 'chart' });
      const hatch = hatchFor(svg, 'h-words', 'var(--advice)');
      svg.append(T(lx + 12, 16, 'In the words', 'rowhead'), T(lx + 12, 33, 'share of answers naming local context', 'axis-label'),
        T(470, 16, 'In the number', 'rowhead'), T(470, 33, 'recommended stock share', 'axis-label'));
      const ax = S('g', { class: 'axis' });
      for (const [sc] of [[xw], [xn]]) for (const t of [0, 0.5, 1]) {
        ax.appendChild(S('line', { class: 'grid', x1: sc(t), x2: sc(t), y1: top - 4, y2: H - 26 }));
        ax.appendChild(T(sc(t), H - 9, pct(t), null, { 'text-anchor': 'middle' }));
      }
      svg.appendChild(ax);
      const marks = rows.map((c, i) => {
        const y = top + i * rowH, mid = y + rowH / 2, col = WHO[c.key];
        svg.appendChild(T(lx, mid + 4.5, nameOf(c), 'rowlbl', { 'text-anchor': 'end', fill: col || 'var(--ink-2)' }));
        const bar = S('rect', { x: xw(0), y: y + 2.5, height: rowH - 5, width: xw(c.localB) - xw(0), fill: hatch, stroke: col || 'var(--advice)', 'stroke-width': col ? 2 : 1.1 });
        const ghost = S('circle', { cx: xn(c.mean), cy: mid, r: 5, fill: 'none', stroke: 'var(--ink-3)', 'stroke-width': 1.2, 'stroke-dasharray': '2 2', opacity: 0 });
        const dot = col ? markAt(c, xn(c.mean), mid, 8.5) : S('circle', { cx: xn(c.mean), cy: mid, r: 5, fill: 'var(--advice)' });
        svg.append(bar, ghost, dot);
        let val = null, nval = null;
        if (col) {
          val = T(xw(c.localB) + 6, mid + 4.5, pct(c.localB), 'lbl-mono halo', { fill: col });
          nval = T(xn(c.mean) + 13, mid + 4.5, pct(c.mean), 'lbl-mono halo', { fill: col });
          svg.append(val, nval);
        }
        return { c, bar, dot, ghost, val, nval };
      });
      const tg = L.toggle('Name the local instruments in the prompt (Version C)', false, 'dk-words-c');
      const note = live(el, '.live-note');
      const say = (on) => {
        if (!note) return;
        note.innerHTML = on
          ? `Version C: local references rise by <span class="num">${sgn(D.stats.phiText)}</span> points. The recommended share moves by <span class="num">${sgn(D.stats.phi)}</span>.`
          : 'Version B: the question is translated, the instruments are generic.';
      };
      const set = (on) => {
        move(marks.flatMap((mk) => [
          { el: mk.bar, attr: 'width', to: xw(on ? mk.c.localC : mk.c.localB) - xw(0) },
          { el: mk.dot, attr: WHO[mk.c.key] ? 'tx' : 'cx', to: xn(on ? mk.c.meanC : mk.c.mean) }]), 900);
        marks.forEach((mk) => {
          mk.ghost.setAttribute('opacity', on ? 1 : 0);
          if (mk.val) {
            const v = on ? mk.c.localC : mk.c.localB, n = on ? mk.c.meanC : mk.c.mean;
            mk.val.textContent = pct(v); mk.val.setAttribute('x', Math.min(xw(v) + 6, 434));
            mk.nval.textContent = pct(n); mk.nval.setAttribute('x', xn(n) + 13);
          }
        });
        say(on);
      };
      tg.input.addEventListener('change', () => set(tg.input.checked));
      say(false);
      el.append(E('div', { class: 'ctl' }, [tg.row]), wrap(svg),
        cap(`Hatched: the words, coded by a separate model shown only the explanation. Solid: the number. One 0–100% scale for both. Question 1, age 40. Naming each country’s own pension, bonds and index fund (Version C) raises local references by ${sgn(D.stats.phiText)} points and moves the share by ${sgn(D.stats.phi)}. Dashed rings: the Version B position.`));
    };
    // =====================================================================
    // three: country effects on the portfolio, mortgage and inflation questions (chips)
    // =====================================================================
    CH.three = (el) => {
      const Q = {
        q1: { name: 'Portfolio', get: (c) => c.fe, v: D.variance.q1 },
        q2: { name: 'Mortgage', get: (c) => c.q2, v: D.variance.q2 },
        q3: { name: 'Inflation', get: (c) => c.q3, v: D.variance.q3 },
      };
      const rows = C.filter((c) => c.fe).sort((a, b) => a.fe.est - b.fe.est);
      const W = 740, top = 14, rowH = 17, H = top + rows.length * rowH + 44, lx = 124;
      const x = L.scale(-31, 5, lx + 12, 510);
      const svg = S('svg', { viewBox: `0 0 ${W} ${H}`, class: 'chart' });
      const ax = S('g', { class: 'axis' });
      for (let t = -30; t <= 0; t += 10) {
        ax.appendChild(S('line', { class: 'grid', x1: x(t), x2: x(t), y1: top - 6, y2: H - 40 }));
        ax.appendChild(T(x(t), H - 23, minus(t), null, { 'text-anchor': 'middle' }));
      }
      ax.appendChild(T(x(-13), H - 3, 'percentage points relative to the U.S.', 'axis-label', { 'text-anchor': 'middle' }));
      svg.appendChild(ax);
      svg.appendChild(S('line', { x1: x(0), x2: x(0), y1: top - 8, y2: H - 40, stroke: 'var(--emily)', 'stroke-width': 2 }));
      const marks = rows.map((c, i) => {
        const y = top + i * rowH + rowH / 2;
        svg.appendChild(T(lx, y + 4.5, nameOf(c), 'rowlbl', { 'text-anchor': 'end', fill: WHO[c.key] || 'var(--ink-2)' }));
        const line = S('line', { x1: x(0), x2: x(c.fe.est), y1: y, y2: y, stroke: 'var(--line)', 'stroke-width': 1.5 });
        const dot = WHO[c.key] ? markAt(c, x(c.fe.est), y, 9.5, c.fe.sig) : effectDot(c, c.fe, { cx: x(c.fe.est), cy: y });
        const dia = S('path', { d: 'M0 -7 L7 0 L0 7 L-7 0 Z', transform: `translate(${x(c.fe.est)},${y})`, fill: 'var(--paper)', stroke: 'var(--advice)', 'stroke-width': 2, opacity: 0 });
        svg.append(line, dot, dia);
        return { c, dot, dia, line, y };
      });
      // variance panel: which model, which country, and the rest
      const vx = 560, vw = 160, vy = 40;
      const vg = S('g');
      vg.append(T(vx, vy - 20, 'Share of the variance', 'rowhead'), T(vx, vy - 3, 'in the advice explained by', 'axis-label'));
      const vb = [['model', 'which model'], ['country', 'which country'], ['rest', 'the rest']].map(([k, label], i) => {
        const y = vy + 22 + i * 50;
        const bg = S('rect', { x: vx, y: y + 8, width: vw, height: 16, fill: 'var(--paper-3)' });
        const bar = S('rect', { x: vx, y: y + 8, width: 0, height: 16, fill: k === 'rest' ? 'var(--line)' : 'var(--ink-2)' });
        const val = T(vx + vw, y, '', 'lbl-mono', { 'text-anchor': 'end' });
        vg.append(T(vx, y, label, 'rowlbl'), bg, bar, val); return { k, bar, val };
      });
      svg.appendChild(vg);
      const leg1 = T(vx, vy + 190, 'Filled: survives Holm', 'lbl-sm'), leg2 = T(vx, vy + 208, '', 'lbl-sm');
      svg.append(leg1, leg2);
      const share = (G, k) => (k === 'rest' ? 100 - G.v.model - G.v.country : G.v[k]);

      const set = (q, first) => {
        const G = Q[q];
        marks.forEach((mk) => {
          const e = G.get(mk.c), prem = q === 'q2' && mk.c.premise, col = WHO[mk.c.key] || 'var(--advice)';
          if (WHO[mk.c.key]) paintMark(mk.dot, mk.c, e.sig);
          else { mk.dot.setAttribute('fill', e.sig ? col : 'var(--paper)'); mk.dot.setAttribute('stroke', col); }
          mk.dot.setAttribute('opacity', prem ? 0 : 1);
          mk.dia.setAttribute('opacity', prem ? 1 : 0); mk.dia.setAttribute('fill', e.sig ? 'var(--advice)' : 'var(--paper)');
          mk.dia.setAttribute('transform', `translate(${x(e.est)},${mk.y})`);
          if (first) { if (WHO[mk.c.key]) setT(mk.dot, 'tx', x(e.est)); else mk.dot.setAttribute('cx', x(e.est)); mk.line.setAttribute('x2', x(e.est)); }
        });
        if (!first) move(marks.flatMap((mk) => [{ el: mk.dot, attr: WHO[mk.c.key] ? 'tx' : 'cx', to: x(G.get(mk.c).est) }, { el: mk.line, attr: 'x2', to: x(G.get(mk.c).est) }]), 900);
        vb.forEach((b) => {
          const s = share(G, b.k);
          if (first) b.bar.setAttribute('width', vw * s / 100); else move([{ el: b.bar, attr: 'width', to: vw * s / 100 }], 900);
          b.val.textContent = Math.round(s) + '%';
        });
        leg2.textContent = q === 'q2' ? '◇ local rates far above 4%' : '';
        press(bar, (b) => b.dataset.q === q);
        const note = live(el, '.live-note');
        const jp = G.get(byKey.Japan);
        const lvl = q === 'q2' ? ` She is told to invest ${pct(byKey.Japan.q2mean)} of her savings, Emily ${pct(byKey.USA.q2mean)}.` : '';
        if (note) note.innerHTML = `${G.name} question: Yuki’s Japan <span class="num" style="color:var(--yuki)">${sgn(jp.est)}</span> points against the U.S.${lvl}`;
      };
      const bar = E('div', { class: 'ctl' }, Object.keys(Q).map((q) => { const b = chip(Q[q].name, q === 'q1', () => set(q)); b.dataset.q = q; return b; }));
      el.append(bar, wrap(svg), cap(`Country effects with model fixed effects, Version B, age 40, one regression per question. On the mortgage question fifteen countries sit 10 to 29 points below the U.S., and the country’s share of the variance rises from ${Math.round(D.variance.q1.country)}% to ${Math.round(D.variance.q2.country)}% while the model’s falls from ${Math.round(D.variance.q1.model)}% to ${Math.round(D.variance.q2.model)}%. Rows keep the portfolio order.`));
      set('q1', true);
    };

    // =====================================================================
    // bench: advice against the Merton benchmark, unhedged or hedged (one toggle)
    // =====================================================================
    CH.bench = (el) => {
      const rows = [...C].sort((a, b) => a.alphaS - b.alphaS);
      const W = 760, top = 12, rowH = 16.6, H = top + rows.length * rowH + 44, lx = 124;
      const x = L.scale(0.15, 0.65, lx + 14, W - 20);
      const svg = S('svg', { viewBox: `0 0 ${W} ${H}`, class: 'chart' });
      const ax = S('g', { class: 'axis' });
      for (let t = 0.2; t <= 0.61; t += 0.1) {
        ax.appendChild(S('line', { class: 'grid', x1: x(t), x2: x(t), y1: top - 4, y2: H - 40 }));
        ax.appendChild(T(x(t), H - 23, pct(t), null, { 'text-anchor': 'middle' }));
      }
      ax.appendChild(T(x(0.40), H - 3, 'share in the stock fund', 'axis-label', { 'text-anchor': 'middle' }));
      svg.appendChild(ax);
      const marks = rows.map((c, i) => {
        const y = top + i * rowH + rowH / 2;
        svg.appendChild(T(lx, y + 4.5, nameOf(c), 'rowlbl', { 'text-anchor': 'end', fill: WHO[c.key] || 'var(--ink-2)' }));
        const gap = S('line', { x1: x(c.alphaS), x2: x(c.adviceBench), y1: y, y2: y, stroke: 'var(--line)', 'stroke-width': 3 });
        const ring = S('circle', { cx: x(c.alphaS), cy: y, r: 6, fill: 'var(--paper)', stroke: 'var(--theory)', 'stroke-width': 2.5 });
        const dot = WHO[c.key] ? markAt(c, x(c.adviceBench), y, 8.5) : S('circle', { cx: x(c.adviceBench), cy: y, r: 5.5, fill: 'var(--advice)' });
        svg.append(gap, ring, dot);
        return { c, gap, ring };
      });
      const tg = L.toggle('The world fund is currency-hedged', false, 'dk-bench-h');
      const note = live(el, '.live-note');
      const maxGapH = D.stats.gapHedgedMax;
      const say = (on) => {
        if (!note) return;
        const lo = rows[0], hi = rows[rows.length - 1];
        note.innerHTML = on
          ? `Hedged: theory prescribes <span class="num">${pct(byKey.USA.alphaH)}</span> in every country, and the advice is within <span class="num">${(100 * maxGapH).toFixed(0)}</span> points of it everywhere.`
          : `Unhedged, the yen adds exchange-rate risk: theory gives Yuki <span class="num">${pct(byKey.Japan.alphaS)}</span> and Emily <span class="num">${pct(byKey.USA.alphaS)}</span>, and runs from ${pct(lo.alphaS)} in ${lo.label} to ${pct(hi.alphaS)} in ${hi.label}. The slope of advice on theory is <span class="num">${D.stats.kappa.toFixed(2)}</span>.`;
      };
      tg.input.addEventListener('change', () => {
        const on = tg.input.checked;
        move(marks.flatMap((mk) => [{ el: mk.ring, attr: 'cx', to: x(on ? mk.c.alphaH : mk.c.alphaS) }, { el: mk.gap, attr: 'x1', to: x(on ? mk.c.alphaH : mk.c.alphaS) }]), 1000);
        say(on);
      });
      say(false);
      el.append(E('div', { class: 'ctl' }, [tg.row, E('span', { class: 'legend' }, [E('span', { class: 'dot', style: '--c:var(--advice)', text: 'advice' }), E('span', { class: 'ring', style: '--c:var(--theory)', text: 'theory' })])]),
        wrap(svg), cap(`Advice: mean recommendation, Question 1, Version B, age 40. Theory: the Merton share for the stake alone at relative risk aversion 3, with the world index’s volatility in each currency. Hedged, theory is ${pct(byKey.USA.alphaH)} everywhere and the advice is within ${(100 * maxGapH).toFixed(0)} points of it.`));
    };

    // =====================================================================
    // levers: what moves the number (build-in once)
    // =====================================================================
    CH.levers = (el, o) => {
      const s = D.stated, st = D.stats, br = byKey.Brazil.fe;
      const rows = [
        { g: 'A sentence about the investor', label: 'Stated risk tolerance', sub: 'comfortable vs. uncomfortable with swings', e: s.risk },
        { label: 'Stated horizon', sub: '20 years vs. 1 year', e: s.horizon, theory: { kind: 'zero', text: 'CRRA, i.i.d. returns: 0' } },
        { label: 'Stated pension', sub: 'substantial vs. small', e: s.pension, theory: { kind: 'up', text: 'lifecycle planner: up' } },
        { g: 'The country of the investor', label: 'Largest country contrast', sub: 'Brazil vs. U.S.', e: br },
        { label: 'Local language', sub: 'vs. the same prompt in English', e: { est: st.lambda, lo: st.lambdaLo, hi: st.lambdaHi } },
        { label: 'Local instruments named', sub: 'Version C vs. B', e: { est: st.phi, lo: st.phiLo, hi: st.phiHi } },
      ];
      const W = 1100, top = 30, rowH = 50, gapG = 30, lx = 300;
      const H = top + rows.length * rowH + gapG + 40;
      const x = L.scale(-15, 56, lx + 16, W - 110);
      const svg = S('svg', { viewBox: `0 0 ${W} ${H}`, class: 'chart' });
      const ax = S('g', { class: 'axis' });
      for (let t = -10; t <= 50; t += 10) {
        ax.appendChild(S('line', { class: 'grid', x1: x(t), x2: x(t), y1: top - 10, y2: H - 40 }));
        ax.appendChild(T(x(t), H - 23, minus(t), null, { 'text-anchor': 'middle' }));
      }
      ax.appendChild(T(x(20), H - 3, 'percentage points of stock', 'axis-label', { 'text-anchor': 'middle' }));
      svg.appendChild(ax);
      svg.appendChild(S('line', { x1: x(0), x2: x(0), y1: top - 12, y2: H - 40, stroke: 'var(--ink-3)' }));
      const defs = S('defs');
      const mk = S('marker', { id: 'arr-theory', viewBox: '0 0 10 10', refX: 8, refY: 5, markerWidth: 7, markerHeight: 7, orient: 'auto' });
      mk.appendChild(S('path', { d: 'M0 0 L10 5 L0 10 z', fill: 'var(--theory)' }));
      defs.appendChild(mk); svg.appendChild(defs);
      const bars = [], extras = [];
      let y = top;
      rows.forEach((r, i) => {
        if (r.g) { if (i) y += gapG; svg.appendChild(T(0, y - 6, r.g.toUpperCase(), 'eyebrow-svg')); }
        const mid = y + rowH / 2, e = r.e;
        svg.append(T(lx, mid - 2, r.label, 'rowlbl-strong', { 'text-anchor': 'end' }), T(lx, mid + 15, r.sub, 'lbl-sm', { 'text-anchor': 'end' }));
        const bx = Math.min(x(0), x(e.est)), bw = Math.abs(x(e.est) - x(0));
        const bar = S('rect', { x: bx, y: mid - 11, width: bw, height: 22, fill: 'var(--advice)' });
        const ci = S('line', { x1: x(e.lo), x2: x(e.hi), y1: mid, y2: mid, stroke: 'var(--ink)', 'stroke-width': 1.6 });
        const val = T(x(Math.max(e.hi, 0)) + 10, mid + 5, sgn(e.est), 'lbl-mono');
        svg.append(bar, ci, val);
        bars.push({ bar, full: { x: bx, w: bw }, zero: x(0) });
        extras.push(val, ci);
        if (r.theory) {
          const tg = S('g');
          if (r.theory.kind === 'zero') {
            tg.append(S('path', { d: `M${x(0)} ${mid - 18} v36`, stroke: 'var(--theory)', 'stroke-width': 3.5 }),
              T(x(0) - 8, mid + 5, r.theory.text, 'lbl-sm halo', { 'text-anchor': 'end', fill: 'var(--theory)' }));
          } else {
            tg.append(S('path', { d: `M${x(0) + 76} ${mid} H${x(0) + 126}`, stroke: 'var(--theory)', 'stroke-width': 3, 'marker-end': 'url(#arr-theory)' }),
              T(x(0) + 134, mid + 5, r.theory.text, 'lbl-sm', { fill: 'var(--theory)' }));
          }
          svg.appendChild(tg); extras.push(tg);
        }
        y += rowH;
      });
      el.append(wrap(svg), cap(`Vermilion: measured effects on the recommended stock share with 95% wild cluster bootstrap intervals, country and model fixed effects. Investor rows: the English prompt with one added sentence, all 21 countries. The pension effect is for the risk-averse investor and ${sgn(s.pension.est + s.inter.est)} for the risk-tolerant one. Teal: the direction theory predicts, not its size.`));
      if (!o.animate) return;
      bars.forEach((b) => { b.bar.setAttribute('width', 0); b.bar.setAttribute('x', b.zero); });
      extras.forEach((g) => g.setAttribute('opacity', 0));
      const timers = bars.map((b, i) => setTimeout(() => L.tween(0, 1, 700, (k) => {
        const w = b.full.w * k; b.bar.setAttribute('width', w); b.bar.setAttribute('x', b.full.x < b.zero ? b.zero - w : b.zero);
      }), 250 + i * 380));
      timers.push(setTimeout(() => L.tween(0, 1, 500, (k) => extras.forEach((g) => g.setAttribute('opacity', k))), 250 + bars.length * 380 + 300));
      return () => timers.forEach(clearTimeout);
    };
    // =====================================================================
    // asym: the balance-sheet probes, one row per statement (static)
    // =====================================================================
    CH.asym = (el) => {
      const P = D.probes;
      const W = 760, top = 34, block = 98, H = top + P.length * block + 40, cx = 420, k = 8.2, lblR = 548;
      const x = (v) => cx + v * k;
      const svg = S('svg', { viewBox: `0 0 ${W} ${H}`, class: 'chart' });
      svg.append(T(cx - 12, 14, '◂ the statement adds exposure', 'rowhead', { 'text-anchor': 'end' }),
        T(cx + 12, 14, 'the statement adds safety ▸', 'rowhead'));
      const ax = S('g', { class: 'axis' });
      for (const t of [-20, -10, 0, 10]) {
        ax.appendChild(S('line', { class: 'grid', x1: x(t), x2: x(t), y1: top - 6, y2: H - 40 }));
        ax.appendChild(T(x(t), H - 23, t > 0 ? '+' + t : minus(t), null, { 'text-anchor': 'middle' }));
      }
      ax.appendChild(T(cx, H - 3, 'percentage points of stock against the prompt with no added sentence', 'axis-label', { 'text-anchor': 'middle' }));
      svg.appendChild(ax);
      svg.appendChild(S('line', { x1: cx, x2: cx, y1: top - 8, y2: H - 40, stroke: 'var(--ink-3)', 'stroke-width': 1.5 }));
      const row = (y, text, e, side) => {
        const b0 = Math.min(x(0), x(e.est)), bw = Math.abs(x(e.est) - x(0));
        svg.append(S('rect', { x: b0, y: y - 10, width: Math.max(bw, 1.5), height: 20, fill: 'var(--advice)' }),
          S('line', { x1: x(e.lo), x2: x(e.hi), y1: y, y2: y, stroke: 'var(--ink)', 'stroke-width': 1.5 }));
        if (side === 'risk') {
          const end = Math.min(x(e.lo), x(e.est));
          svg.append(S('line', { x1: 196, x2: end - 6, y1: y, y2: y, stroke: 'var(--line)', 'stroke-dasharray': '2 3' }),
            T(0, y + 5, '◂', 'lbl-sm', { fill: 'var(--theory)' }), T(16, y + 5, `“${text}”`, 'rowlbl'),
            T(x(Math.max(e.hi, 0)) + 8, y + 5, sgn(e.est), 'lbl-mono halo'));
        } else {
          const end = Math.max(x(e.hi), x(e.est));
          svg.append(T(end + 8, y + 5, sgn(e.est), 'lbl-mono halo'),
            S('line', { x1: end + 50, x2: lblR - 6, y1: y, y2: y, stroke: 'var(--line)', 'stroke-dasharray': '2 3' }),
            T(lblR, y + 5, `“${text}”`, 'rowlbl'), T(W - 2, y + 5, '▸', 'lbl-sm', { 'text-anchor': 'end', fill: 'var(--theory)' }));
        }
      };
      P.forEach((p, i) => {
        const y = top + i * block;
        svg.appendChild(T(16, y + 14, p.pair + (p.scope === 'United States' ? ', U.S. prompt only' : ', all 21 countries'), 'rowlbl-strong'));
        row(y + 40, p.risk, p.r, 'risk');
        row(y + 70, p.safe, p.s, 'safe');
      });
      el.append(wrap(svg), cap(`Vermilion: measured effect of one added sentence with 95% intervals, exploratory probes of August 2026, English Question 1 at age 40, country and model fixed effects. Teal ◂ ▸: the direction a balance-sheet planner predicts, a cut on the left and a rise on the right. The half-of-liquid-wealth statement gives ${sgn(P[1].half.est)}.`));
    };

    // =====================================================================
    // ending: the same number, in local words
    // =====================================================================
    CH.ending = (el) => {
      const q = D.quotes;
      const col = (who, place, cls, color, soft, sym, frac, words) => E('div', { class: 'end-col ' + cls }, [
        person(who, place, cls, color, soft, sym),
        E('div', { class: 'end-num', text: pct(frac) }),
        E('div', { class: 'bar6040', 'aria-hidden': 'true' }),
        E('div', { class: 'end-words', html: words })]);
      el.append(E('div', { class: 'hook' }, [
        col('Emily', 'Ohio', 'emily', 'var(--emily)', 'var(--emily-soft)', '$', q.us.fraction, '“a classic balanced approach”'),
        col('Yuki', 'Osaka', 'yuki', 'var(--yuki)', 'var(--yuki-soft)', '¥', q.jp.fraction, '“use tax-free schemes such as NISA”')]),
        cap(`${q.model}, the pair of real answers shown earlier. Averaged over all 13 models: U.S. ${pct(byKey.USA.mean)}, Japan ${pct(byKey.Japan.mean)}.`));
    };

    // =====================================================================
    // answers: the real pair of replies, which arrive together (build-in once)
    // =====================================================================
    CH.answers = (el, o) => {
      const q = D.quotes;
      const reply = (cls, who, frac, html) => {
        const pill = E('span', { class: 'ans', text: pct(frac) });
        const body = E('div', { class: 'reply-body', html });
        const dots = E('div', { class: 'typing', 'aria-hidden': 'true' }, [E('i'), E('i'), E('i')]);
        return { box: E('div', { class: 'chat reply ' + cls }, [pill, E('span', { class: 'who', text: who }), body, dots]), pill, body, dots };
      };
      const cue = (t, phrase) => t.replace(phrase, `<span class="cue">${phrase}</span>`);
      const A = reply('emily', 'The model to Emily', q.us.fraction, cue(q.us.text, 'a classic balanced approach'));
      const B = reply('yuki jp', 'The model to Yuki', q.jp.fraction, cue(q.jp.text, '日本の居住者としては、NISA等の非課税制度を活用し') + `<span class="gloss">“${q.jp.gloss}”</span>`);
      el.append(E('div', { class: 'answers' }, [A.box, B.box]));
      if (!o.animate) { [A, B].forEach((r) => r.dots.remove()); return; }
      [A, B].forEach((r) => { r.pill.style.opacity = 0; r.body.style.opacity = 0; });
      const t = setTimeout(() => [A, B].forEach((r) => { r.dots.remove(); r.pill.style.opacity = 1; r.body.style.opacity = 1; }), 1500);
      return () => clearTimeout(t);
    };

    // fan: the 60/40 motif once per model, split at the model's average advice
    CH.fan = (el) => {
      const ms = [...D.models].sort((a, b) => a.mean - b.mean);
      const W = 560, rowH = 24, lx = 150, bw = 330, H = ms.length * rowH + 8;
      const svg = S('svg', { viewBox: `0 0 ${W} ${H}`, class: 'chart' });
      ms.forEach((md, i) => {
        const y = 4 + i * rowH, split = lx + bw * md.mean;
        svg.append(T(lx - 12, y + 12, md.name, 'lbl-sm', { 'text-anchor': 'end' }),
          S('rect', { x: lx, y: y + 3, width: bw * md.mean, height: 10, fill: 'var(--advice)' }),
          S('rect', { x: split + 3, y: y + 3, width: Math.max(0, lx + bw - split - 3), height: 10, fill: 'var(--line)' }),
          T(lx + bw + 10, y + 12, pct(md.mean), 'lbl-mono'));
      });
      el.append(wrap(svg), cap('The 60/40 bar once for each model, split at its average recommended stock share (the portfolio question, Version B, age 40).'));
    };

    // =====================================================================
    // Rooms
    // =====================================================================

    // grid: the 21 × 13 country-by-model cell means
    CH.grid = (el) => {
      const ms = [...D.models].sort((a, b) => a.mean - b.mean);
      const rows = [...C].sort((a, b) => a.mean - b.mean);
      const W = 1120, lx = 124, top = 96, cw = (W - lx - 10) / ms.length, ch = 17, H = top + rows.length * ch + 6;
      const svg = S('svg', { viewBox: `0 0 ${W} ${H}`, class: 'chart' });
      const lo = 0.20, hi = 0.76;
      const ramp = (v) => { const t = L.clamp((v - lo) / (hi - lo), 0, 1); return `color-mix(in srgb, var(--advice) ${Math.round(8 + 82 * t)}%, var(--paper))`; };
      ms.forEach((md, j) => {
        const cx = lx + j * cw + cw / 2;
        svg.appendChild(T(cx - 4, top - 8, md.name, 'lbl-sm', { transform: `rotate(-32 ${cx - 4} ${top - 8})` }));
      });
      rows.forEach((c, i) => {
        const y = top + i * ch;
        svg.appendChild(T(lx - 8, y + ch / 2 + 4.5, nameOf(c), 'rowlbl', { 'text-anchor': 'end', fill: WHO[c.key] || 'var(--ink-2)' }));
        ms.forEach((md, j) => {
          const v = D.grid[c.key][md.name];
          svg.appendChild(S('rect', { x: lx + j * cw + 1, y: y + 1, width: cw - 2, height: ch - 2, fill: ramp(v) }));
          svg.appendChild(T(lx + j * cw + cw / 2, y + ch / 2 + 4.5, Math.round(100 * v), 'cell', { 'text-anchor': 'middle', fill: v > 0.55 ? 'var(--paper)' : 'var(--ink)' }));
        });
      });
      el.append(wrap(svg), cap('Mean recommended stock share in percent, Question 1, Version B, age 40, 50 answers per cell, from the collection. Columns ordered by model mean, rows by country mean.'));
    };

    // round: the answers at ages 30, 40 and 55 against 100 minus age
    CH.round = (el) => {
      const W = 1120, H = 340, pw = 330, gap = 60;
      const svg = S('svg', { viewBox: `0 0 ${W} ${H}`, class: 'chart' });
      ['30', '40', '55'].forEach((a, i) => {
        const h = D.histByAge[a], n = Object.values(h).reduce((s, v) => s + v, 0);
        const x0 = 50 + i * (pw + gap), x = L.scale(5, 95, x0, x0 + pw), y = L.scale(0, 0.40, H - 50, 44);
        svg.appendChild(T(x0, 22, `Age ${a}`, 'rowhead'));
        const ax = S('g', { class: 'axis' });
        for (const t of [0, 0.2, 0.4]) {
          ax.appendChild(S('line', { class: 'grid', x1: x0, x2: x0 + pw, y1: y(t), y2: y(t) }));
          ax.appendChild(T(x0 - 6, y(t) + 4, pct(t), null, { 'text-anchor': 'end' }));
        }
        ax.appendChild(S('line', { x1: x0, x2: x0 + pw, y1: H - 50, y2: H - 50 }));
        for (const t of [20, 40, 60, 80]) ax.appendChild(T(x(t), H - 32, t + '%', null, { 'text-anchor': 'middle' }));
        svg.appendChild(ax);
        for (let v = 10; v <= 90; v += 5) {
          const s = (h[String(v)] || 0) / n;
          svg.appendChild(S('rect', { x: x(v) - 7, y: y(s), width: 14, height: y(0) - y(s), fill: v % 10 ? 'var(--advice-soft)' : 'var(--advice)' }));
        }
        const rule = D.age[a].rule;
        svg.append(S('line', { x1: x(rule), x2: x(rule), y1: 36, y2: H - 50, stroke: 'var(--ink)', 'stroke-width': 2, 'stroke-dasharray': '6 4' }),
          T(x(rule) + 6, 46, `100 − ${a} = ${rule}`, 'lbl-sm halo', { fill: 'var(--ink)' }));
      });
      svg.appendChild(T(W / 2, H - 6, 'recommended share in the stock fund (x) and share of answers at each value (y)', 'axis-label', { 'text-anchor': 'middle' }));
      el.append(wrap(svg), cap(`Question 1, Version B, all 21 countries and 13 models, from the collection. Dark bars: multiples of ten. Dashed: the 100-minus-age rule of thumb. Pooled advice falls ${Math.abs(D.slopes.pooled).toFixed(2)} points per year of age against the rule's 1.00.`));
    };

    // decomp: per-country slabs of the fully localized effect
    CH.decomp = (el) => {
      const rows = C.filter((c) => c.decomp).sort((a, b) => a.decomp.total - b.decomp.total);
      const W = 1120, top = 16, rowH = 18, lx = 130, H = top + rows.length * rowH + 44;
      const x = L.scale(-18, 8, lx + 10, W - 30);
      const svg = S('svg', { viewBox: `0 0 ${W} ${H}`, class: 'chart' });
      const ax = S('g', { class: 'axis' });
      for (let t = -15; t <= 5; t += 5) {
        ax.appendChild(S('line', { class: 'grid', x1: x(t), x2: x(t), y1: top - 6, y2: H - 40 }));
        ax.appendChild(T(x(t), H - 23, minus(t), null, { 'text-anchor': 'middle' }));
      }
      ax.appendChild(T(x(-5), H - 3, 'percentage points relative to the U.S. English generic prompt', 'axis-label', { 'text-anchor': 'middle' }));
      svg.appendChild(ax);
      svg.appendChild(S('line', { x1: x(0), x2: x(0), y1: top - 8, y2: H - 40, stroke: 'var(--ink-3)' }));
      const fills = { name: 'var(--ink-2)', lang: '#8A9195', local: 'var(--line)' };
      rows.forEach((c, i) => {
        const y = top + i * rowH, d = c.decomp;
        svg.appendChild(T(lx, y + rowH / 2 + 4.5, nameOf(c), 'rowlbl', { 'text-anchor': 'end', fill: WHO[c.key] || 'var(--ink-2)' }));
        let pos = 0, neg = 0;
        for (const k of ['name', 'lang', 'local']) {
          const v = d[k]; if (!v) continue;
          const a = v >= 0 ? pos : neg, b = a + v;
          svg.appendChild(S('rect', { x: x(Math.min(a, b)), y: y + 3, width: Math.abs(x(b) - x(a)), height: rowH - 6, fill: fills[k] }));
          if (v >= 0) pos = b; else neg = b;
        }
        svg.appendChild(S('path', { d: `M${x(d.total)} ${y + 2} l5 ${rowH / 2 - 2} l-5 ${rowH / 2 - 2} l-5 ${-(rowH / 2 - 2)} z`, fill: 'var(--ink)' }));
      });
      el.append(E('div', { class: 'legend' }, [E('span', { style: '--c:var(--ink-2)', text: 'country name (B-cross vs. U.S.)' }), E('span', { style: '--c:#8A9195', text: 'language (B vs. B-cross)' }), E('span', { style: '--c:var(--line)', text: 'local instruments (C vs. B)' }), E('span', { class: 'diamond', text: 'total (C vs. U.S.)' })]),
        wrap(svg), cap('Model-adjusted cell contrasts from one saturated country-by-version regression, Question 1, age 40. Descriptive: the per-country slabs are noisier than the pooled estimates. The six English-prompt countries have no language slab. The country-name slab also changes the currency and the amount.'));
    };

    // mortbench: mortgage advice against the after-tax real-rate benchmark
    CH.mortbench = (el) => {
      const c = L.chart(580, 430, { l: 56, r: 24, t: 24, b: 50 }, [0, 1], [0.4, 1]);
      L.axisY(c, [0.4, 0.6, 0.8, 1], (v) => pct(v), 'advice: share invested');
      L.axisX(c, [0, 0.2, 0.4, 0.6, 0.8, 1], (v) => pct(v), 'theory: benchmark share');
      c.g.appendChild(S('line', { x1: c.x(0.4), x2: c.x(1), y1: c.y(0.4), y2: c.y(1), stroke: 'var(--theory)', 'stroke-width': 2, 'stroke-dasharray': '6 4' }));
      c.g.appendChild(T(c.x(0.66), c.y(0.47), 'advice = theory', 'lbl-sm halo', { fill: 'var(--theory)' }));
      const lab = { USA: [10, -10], Japan: [10, 5], Brazil: [-10, -10, 'end'], 'South Africa': [-10, -12, 'end'], India: [10, 18], China: [10, 16], Sweden: [10, 4] };
      C.forEach((k) => {
        const col = WHO[k.key] || 'var(--advice)';
        if (k.premise) c.g.appendChild(S('path', { d: 'M0 -7 L7 0 L0 7 L-7 0 Z', transform: `translate(${c.x(k.q2alpha)},${c.y(k.q2mean)})`, fill: 'var(--paper)', stroke: col, 'stroke-width': 2 }));
        else c.g.appendChild(WHO[k.key] ? markAt(k, c.x(k.q2alpha), c.y(k.q2mean), 8) : S('circle', { cx: c.x(k.q2alpha), cy: c.y(k.q2mean), r: 5.5, fill: col }));
        const l = lab[k.key];
        if (l) c.g.appendChild(T(c.x(k.q2alpha) + l[0], c.y(k.q2mean) + l[1], nameOf(k), 'lbl-sm halo', { fill: WHO[k.key] || 'var(--ink-2)', 'text-anchor': l[2] || 'start' }));
      });
      el.append(wrap(c.svg), cap('Question 2, Version B, age 40. Theory: the Merton share with the after-tax real mortgage rate as the safe return (γ = 3, no deductibility). Diamonds: the five countries whose local rates were more than twice the prompted 4%, where the benchmark takes the 4% at face value.'));
    };

    // inflation: primary instrument on the inflation question
    CH.inflation = (el) => {
      const rows = [...C].sort((a, b) => a.inst.eq - b.inst.eq);
      const W = 1120, top = 10, rowH = 18, lx = 130, H = top + rows.length * rowH + 36;
      const x = L.scale(0, 1, lx + 10, W - 40);
      const svg = S('svg', { viewBox: `0 0 ${W} ${H}`, class: 'chart' });
      const parts = [['linker', 'var(--ink)'], ['gold', 'var(--ink-3)'], ['re', '#9AA1A4'], ['other', 'var(--paper-3)'], ['eq', 'var(--line)']];
      rows.forEach((c, i) => {
        const y = top + i * rowH;
        svg.appendChild(T(lx, y + rowH / 2 + 4.5, nameOf(c), 'rowlbl', { 'text-anchor': 'end', fill: WHO[c.key] || 'var(--ink-2)' }));
        let a = 0;
        for (const [k, fill] of parts) {
          const v = c.inst[k]; if (!v) continue;
          svg.appendChild(S('rect', { x: x(a), y: y + 2, width: x(a + v) - x(a), height: rowH - 4, fill }));
          a += v;
        }
        const prot = c.inst.linker + c.inst.gold;
        if (prot > 0.05) svg.appendChild(T(x(prot) + 6, y + rowH / 2 + 4.5, pct(prot), 'lbl-mono halo'));
      });
      const ax = S('g', { class: 'axis' });
      for (const t of [0, 0.25, 0.5, 0.75, 1]) ax.appendChild(T(x(t), H - 16, pct(t), null, { 'text-anchor': 'middle' }));
      svg.appendChild(ax);
      el.append(E('div', { class: 'legend' }, [E('span', { style: '--c:var(--ink)', text: 'inflation-linked bonds' }), E('span', { style: '--c:var(--ink-3)', text: 'gold' }), E('span', { style: '--c:#9AA1A4', text: 'real estate' }), E('span', { style: '--c:var(--paper-3)', text: 'other' }), E('span', { style: '--c:var(--line)', text: 'equities' })]),
        wrap(svg), cap('Share of answers naming each primary instrument, Question 3 (a 1% savings account with 3% inflation), Version B, age 40, from the collection. Labels: inflation-linked bonds plus gold.'));
    };

    // prefs: country effects against GPS risk-taking and financial literacy
    CH.prefs = (el) => {
      const W = 1120, H = 400, st = D.stats, pts = C.filter((k) => k.fe);
      const svg = S('svg', { viewBox: `0 0 ${W} ${H}`, class: 'chart' });
      const y = L.scale(-12, 3, H - 50, 46);
      const panel = (x0, key, xd, xt, fmt, xlab, slope, title) => {
        const x = L.scale(xd[0], xd[1], x0 + 50, x0 + 500);
        const ax = S('g', { class: 'axis' });
        for (const t of [-10, -5, 0]) {
          ax.appendChild(S('line', { class: 'grid', x1: x0 + 50, x2: x0 + 500, y1: y(t), y2: y(t) }));
          ax.appendChild(T(x0 + 44, y(t) + 4, minus(t), null, { 'text-anchor': 'end' }));
        }
        ax.appendChild(S('line', { x1: x0 + 50, x2: x0 + 500, y1: H - 50, y2: H - 50 }));
        for (const t of xt) ax.appendChild(T(x(t), H - 32, fmt(t), null, { 'text-anchor': 'middle' }));
        ax.appendChild(T(x0 + 275, H - 8, xlab, 'axis-label', { 'text-anchor': 'middle' }));
        svg.append(ax, T(x0 + 50, 16, title, 'rowhead'), T(x0 + 50, 33, 'country effect, points against the U.S.', 'axis-label'));
        const mx = pts.reduce((s, k) => s + k[key], 0) / pts.length, my = pts.reduce((s, k) => s + k.fe.est, 0) / pts.length;
        const f = (v) => my + 100 * slope * (v - mx);
        svg.appendChild(S('line', { x1: x(xd[0]), x2: x(xd[1]), y1: y(f(xd[0])), y2: y(f(xd[1])), stroke: 'var(--ink-3)', 'stroke-width': 2, 'stroke-dasharray': '6 4' }));
        pts.forEach((k) => {
          const col = WHO[k.key] || 'var(--advice)';
          svg.appendChild(WHO[k.key] ? markAt(k, x(k[key]), y(k.fe.est), 8, k.fe.sig) : S('circle', { cx: x(k[key]), cy: y(k.fe.est), r: 5.5, fill: k.fe.sig ? col : 'var(--paper)', stroke: col, 'stroke-width': 2 }));
          if (['Japan', 'Brazil', 'South Africa', 'Italy', 'Sweden', 'Turkey', 'India'].includes(k.key)) svg.appendChild(T(x(k[key]) + 9, y(k.fe.est) + 4.5, nameOf(k), 'lbl-sm halo', { fill: WHO[k.key] || 'var(--ink-2)' }));
        });
      };
      panel(0, 'risk', [-0.45, 1.05], [-0.4, 0, 0.4, 0.8], (v) => minus(v.toFixed(1)), 'GPS willingness to take risks', st.gpsSlope,
        `Risk-taking: ${(100 * st.gpsSlope).toFixed(1)} points per unit, p = ${st.gpsP.toFixed(2)}`);
      panel(570, 'finlit', [0.2, 0.75], [0.2, 0.4, 0.6], (v) => pct(v), 'share of adults financially literate', st.finlitSlope,
        `Literacy: ${(10 * st.finlitSlope).toFixed(2)} points per 10 points of literacy, p = ${st.finlitP.toFixed(2)}`);
      el.append(wrap(svg), cap('Country effects (Question 1, Version B, age 40) against Falk et al. (2018) and the S&P Global FinLit Survey, 20 non-U.S. countries. Dashed: the bivariate slope, p from a wild bootstrap over countries. Filled: the country effect survives Holm. Confidence bands in the paper.'));
    };

    // =====================================================================
    // Wiring
    // =====================================================================
    const draw = (el, animate) => {
      if (el._cleanup) { try { el._cleanup(); } catch (e) { /* noop */ } el._cleanup = null; }
      el.replaceChildren();
      const fn = CH[el.dataset.chart];
      if (!fn) { el.appendChild(E('p', { class: 'caption', text: 'unknown chart: ' + el.dataset.chart })); console.error('deck-charts.js: unknown chart ' + el.dataset.chart); return; }
      try { el._cleanup = fn(el, { animate: !!animate }) || null; }
      catch (e) { console.error('deck-charts.js: ' + el.dataset.chart, e); el.appendChild(E('p', { class: 'caption', text: 'This chart failed to draw.' })); }
    };

    const ts = document.getElementById('title-slide');
    if (ts && D.questions && !ts.querySelector('.qwall')) {
      const LANG = { English: 'en', Japanese: 'ja', 'Chinese (simplified)': 'zh-Hans', Korean: 'ko' };
      ts.appendChild(E('div', { class: 'qwall', 'aria-hidden': 'true' }, D.questions.map((q) => E('div', {
        class: 'q-line' + (q.lang === 'English' ? ' en' : '') + (q.lang === 'Japanese' ? ' ja' : '') + (q.lang.startsWith('Chinese') ? ' zh' : '') + (q.lang === 'Korean' ? ' ko' : ''),
        text: q.text, ...(LANG[q.lang] ? { lang: LANG[q.lang] } : {}) }))));
    }

    document.querySelectorAll('.stage[data-chart]').forEach((el) => {
      el.addEventListener('pointerdown', (e) => e.stopPropagation());
      el.addEventListener('click', (e) => { const b = e.target.closest('button'); if (b) b.blur(); });
      el.addEventListener('change', (e) => { if (e.target && e.target.blur) e.target.blur(); }); // a clicked toggle would otherwise eat the arrow keys
      el.addEventListener('pointerup', () => { const a = document.activeElement; if (a && a.tagName === 'INPUT') a.blur(); });
      draw(el, false);
    });
    const animateIn = (section) => {
      if (STATIC || !section) return;
      section.querySelectorAll('.stage[data-animate]').forEach((el) => {
        if (el.dataset.animate === 'once' && el._played) return;
        el._played = true; draw(el, true);
      });
    };
    document.querySelectorAll('.data[data-key]').forEach((sp) => {
      const v = L.get(sp.dataset.key);
      if (v === undefined) { console.error('deck-charts.js: no L.DATA entry for ' + sp.dataset.key); sp.textContent = '?'; return; }
      const n = typeof v === 'number' && sp.dataset.abs !== undefined ? Math.abs(v) : v;
      let txt = typeof n === 'number' && sp.dataset.d !== undefined ? L.fmtNum(n, +sp.dataset.d) : String(n);
      if (sp.dataset.pct !== undefined) txt = (100 * n).toFixed(+sp.dataset.pct);
      if (sp.dataset.sign !== undefined && n > 0) txt = '+' + txt;
      sp.textContent = txt;
    });
    if (window.Reveal && typeof Reveal.on === 'function') {
      Reveal.on('slidechanged', (e) => animateIn(e.currentSlide));
      if (typeof Reveal.getCurrentSlide === 'function') animateIn(Reveal.getCurrentSlide());
    }
  }

  const start = () => {
    if (window.Reveal && typeof Reveal.isReady === 'function' && Reveal.isReady()) main();
    else if (window.Reveal && typeof Reveal.on === 'function') Reveal.on('ready', main);
    else main();
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start); else start();
})();
